          });
        }
      }
    }
    this.unsubscribe = mockBackend.subscribe(roomId, (type, payload) => {
      console.log(`Received: ${type}`, payload);
      const callbackMap = {
        'play': 'onPlay',
        'pause': 'onPause',
        'seek': 'onSeek',
        'change_video': 'onVideoChange',
        'user_joined': 'onUserJoined',
        'user_left': 'onUserLeft',
        'role_assigned': 'onRoleAssigned',
        'participant_removed': 'onParticipantRemoved',
